void OnNavigate(RenderFrameHostImpl* rfh, const FrameHostMsg_DidCommitProvisionalLoad_Params& params, bool is_in_page, bool replace_entry, NavigationHandleImpl* handle) {
    NavigationControllerImpl* controller = rfh->GetNavigationController();
    int64_t navigation_id = handle->navigation_id();
    NavigationEntryImpl* pending_entry = controller->GetPendingEntry();

    if (is_in_page) {
        NavigationEntryImpl* current_entry = controller->GetLastCommittedEntry();
        if (current_entry) {
            NavigationEntryImpl* cloned_entry = current_entry->Clone();
            controller->SetLastCommittedEntry(cloned_entry);
        }
    }

    if (pending_entry && pending_entry == handle->navigation_entry()) {
        NavigationEntryImpl* new_entry = pending_entry->Clone();
        controller->SetEntryBeingNavigatedTo(new_entry);
    } else {
        NavigationEntryImpl* new_entry = NavigationEntryImpl::Create();
        new_entry->SetURL(params.url);
        new_entry->SetVirtualURL(params.url);
        new_entry->SetReferrer(params.referrer);
        new_entry->SetTransitionType(params.transition);
        new_entry->SetPageTransition(params.page_transition);
        new_entry->SetIsInPage(is_in_page);
        controller->SetEntryBeingNavigatedTo(new_entry);
    }

    controller->SetPendingEntry(nullptr);

    if (replace_entry) {
        controller->ReplaceEntry(controller->GetLastCommittedEntryIndex(), controller->GetEntryBeingNavigatedTo());
    } else {
        controller->InsertEntry(controller->GetLastCommittedEntryIndex() + 1, controller->GetEntryBeingNavigatedTo());
    }

    controller->CommitPendingEntry();
}

void HandleNavigationEvent(RenderFrameHostImpl* rfh,
                           const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
                           bool is_in_page,
                           bool replace_entry,
                           NavigationHandleImpl* handle) {
  // Check if the navigation is in-page and clone the current entry if necessary.
  NavigationEntry* entry = nullptr;
  if (is_in_page) {
    entry = navigation_entry()->Clone();
  }

  // Check for a matching pending entry and create a new entry if necessary.
  if (!entry) {
    entry = NavigationEntry::Create();
    entry->SetURL(params.url);
    entry->SetTitle(params.title);
    entry->SetFavicon(params.favicon_url, params.favicon);
    entry->SetTransitionType(handle->GetTransitionType());
    entry->SetReferrer(handle->GetReferrer());
    entry->SetPageTransition(params.transition);
    entry->SetIsOverridingUserAgent(handle->IsOverridingUserAgent());
  }

  // Update the virtual URL if necessary.
  if (!params.virtual_url.IsEmpty()) {
    entry->SetVirtualURL(params.virtual_url);
  }

  // Update the session history based on the navigation state.
  if (replace_entry) {
    history()->ReplaceEntryAt(current_entry_index_, entry);
  } else {
    history()->InsertEntry(entry, current_entry_index_ + 1);
  }

  current_entry_index_ = replace_entry ? current_entry_index_ : current_entry_index_ + 1;
}

