void OnNavigate(RenderFrameHostImpl* rfh,
                const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
                bool is_in_page,
                bool replace_entry,
                NavigationHandleImpl* handle) {
  if (is_in_page) {
    // Clone the current entry for in-page navigation.
    NavigationEntry* cloned_entry = CloneNavigationEntry(rfh->current_entry_);
    rfh->SetCurrentEntry(cloned_entry);
  }

  // Check for a matching pending entry.
  NavigationEntry* pending_entry = FindPendingEntryForHandle(handle);
  if (!pending_entry) {
    // Create a new navigation entry if no matching one is found.
    pending_entry = CreateNewNavigationEntry(params, handle);
  }

  // Update virtual URL and session history.
  pending_entry->SetVirtualURL(params.url);
  UpdateSessionHistory(rfh, pending_entry, replace_entry);

  // Insert or replace the entry in the history.
  if (replace_entry) {
    rfh->ReplaceNavigationEntry(pending_entry);
  } else {
    rfh->InsertNavigationEntry(pending_entry);
  }
}

void HandleNavigationCommit(
    RenderFrameHostImpl* rfh,
    const FrameHostMsg_DidCommitProvisionalLoad_Params& params,
    bool is_in_page,
    bool replace_entry,
    NavigationHandleImpl* handle) {
  NavigationEntry* entry = NULL;
  if (is_in_page) {
    entry = GetLastCommittedEntryForFrame(rfh);
    if (entry)
      entry = entry->Clone();
  }

  if (!entry) {
    if (handle && handle->pending_entry_) {
      entry = handle->pending_entry_->Clone();
    } else {
      entry = new NavigationEntry();
      entry->set_url(params.url);
      entry->set_virtual_url(params.url);
      entry->set_title(params.title);
      entry->set_referrer(params.referrer);
      entry->set_transition_type(params.transition);
      entry->set_safety(params.is_safe);
    }
  }

  if (replace_entry)
    ReplaceLastEntryInHistory(entry);
  else
    InsertEntryInHistory(entry);
}
